import{_ as i,o as t,c as a,a3 as r,j as e,a as s}from"./chunks/framework.z_KJ15Ep.js";const h="/bilder/reportdesigner/mahnungsdruck-einleiten.png",u="/bilder/reportdesigner/tutorials-mahndatum-mahndatum-aendern.png",f=JSON.parse('{"title":"Mahnbriefe drucken","description":"","frontmatter":{"title":"Mahnbriefe drucken","source_pageid":1407,"source_revision":6299},"headers":[],"relativePath":"reporting/reportdesigner/mahnbriefe-drucken-tutorial.md","filePath":"reporting/reportdesigner/mahnbriefe-drucken-tutorial.md"}'),d={name:"reporting/reportdesigner/mahnbriefe-drucken-tutorial.md"};function l(o,n,c,g,m,p){return t(),a("div",null,[...n[0]||(n[0]=[r('<h1 id="mahnbriefe-drucken" tabindex="-1">Mahnbriefe drucken <a class="header-anchor" href="#mahnbriefe-drucken" aria-label="Permalink to &quot;Mahnbriefe drucken&quot;">​</a></h1><p>Bereiten Sie Mahnungen über die Leistungsdaten und den Gruppenprozess vor und erzeugen Sie anschließend die Mahnbriefe oder Übersichtslisten. Die folgenden Schritte unterscheiden ausdrücklich zwischen erstem und zweitem Schulhalbjahr.</p><h2 id="grundlagen-und-voraussetzungen" tabindex="-1">Grundlagen und Voraussetzungen <a class="header-anchor" href="#grundlagen-und-voraussetzungen" aria-label="Permalink to &quot;Grundlagen und Voraussetzungen&quot;">​</a></h2><p>Diese Anleitung dient der komfortablen Erstellung von Mahnschreiben an die Erziehungsberechtigten über den Gruppenprozess <em>Gruppenprozesse ➜ Noten/Zeugnisvorbereitungen</em> ➜ <strong>Mahnungsdruck einleiten</strong></p><p>Im Lauf der Zeit hat sich der Prozess der Erstellung von Mahnschreiben weiterentwickelt. Der Gruppenprozess <strong>Mahnungsdruck einleiten</strong> und der <strong>Serienbrief Mahnung gefährdete Versetzung @Erzieher.rtm</strong> und zwei weitere Übersichten für die Klassenleitungen und Stufenleitungen wurden aufeinander abgestimmt.</p><p>Die Reports für die Mahnungen finden Sie in der <strong>Basisreportsammlung</strong>.</p><h2 id="mahnhakchen-setzen" tabindex="-1">Mahnhäkchen setzen <a class="header-anchor" href="#mahnhakchen-setzen" aria-label="Permalink to &quot;Mahnhäkchen setzen&quot;">​</a></h2><p>Setzen Sie im ersten Halbjahr bei den zu mahnenden Epochalfächern das Mahnhäkchen. Dies ist einzeln unter <strong>Schüler → Akt. Halbjahr → Leistungsdaten</strong> oder gruppenweise mit <strong>Noten, Mahnungen und Fehlstunden eingeben</strong> möglich. Zu jedem Mahnhäkchen kann ein Mahndatum gespeichert werden. Der zugehörige Gruppenprozess kann dieses Datum später automatisch setzen.</p><p>Im zweiten Schulhalbjahr gelten alle Fächer, welche im ersten Schulhalbjahr eine defizitäre Zeugnisnote hatten, als bereits gemahnt. Dies wird beim Versetzungsprozess bereits berücksichtigt, sofern Fächer in das zweite Halbjahr übertragen werden.</p><p>Wurden die Fächer beim Abschnittswechsel nicht übernommen, sondern zum Beispiel über eine Stundentafel neu zugewiesen? Starten Sie dann <strong>Noten/Zeugnisvorbereitungen → Mahnungen automatisch setzen</strong>. Der Prozess wertet die Zeugnisnoten des ersten Halbjahres aus, markiert Fächer mit Minderleistungen und trägt das Zeugnisdatum als Mahndatum ein.</p><p>Kommen im zweiten Halbjahr weitere zu mahnende Fächer hinzu, setzen Sie deren Mahnhäkchen auf dieselbe Weise. Bei diesen neuen Markierungen ist zunächst kein Mahndatum eingetragen.</p><h2 id="der-gruppenprozess-mahnungsdruck-einleiten" tabindex="-1">Der Gruppenprozess Mahnungsdruck einleiten <a class="header-anchor" href="#der-gruppenprozess-mahnungsdruck-einleiten" aria-label="Permalink to &quot;Der Gruppenprozess Mahnungsdruck einleiten&quot;">​</a></h2><p>Streng genommen ist der Gruppenprozess primär ein Filter, welcher auf die zu mahnende Schülergruppe filtert. Der eigentliche Gruppenprozess ist das Setzen des Mahndatums.</p><p><img src="'+h+'" alt="Mahnungsdruck einleiten" loading="lazy"></p><p><em>Mahnungsdruck einleiten</em></p><p>Sind alle Mahnhäkchen gesetzt, wechseln Sie auf den Reiter <em>Gruppenprozesse ➜ Noten/Zeugnisvorbereitungen ➜</em> <strong>Mahnungsdruck einleiten</strong>. Es öffnet sich ein weiteres Fenster mit ausführlicher Beschreibung, um die zu mahnenden Schüler zu filtern und auf Wunsch sofort ein Mahndatum zu setzen.</p><h3 id="schuler-filtern-um-mahnbriefe-zu-drucken" tabindex="-1">Schüler filtern, um Mahnbriefe zu drucken <a class="header-anchor" href="#schuler-filtern-um-mahnbriefe-zu-drucken" aria-label="Permalink to &quot;Schüler filtern, um Mahnbriefe zu drucken&quot;">​</a></h3><p>Wenn Sie die Schaltfläche <strong>Schüler filtern, um Mahnbriefe zu drucken</strong> aktivieren und dann den Filter auslösen, so werden im <strong>ersten Halbjahr</strong> alle minderjährigen Schülerinnen und Schüler gefiltert, bei denen ein gemahntes Fach gefunden wird.</p><p>Im <strong>zweiten Schulhalbjahr</strong> werden alle minderjährigen Schülerinnen und Schüler gefiltert, bei denen ein gemahntes Fach gefunden wird, dessen Mahndatum nicht dem Datum der Zeugnisausgabe des ersten Schulhalbjahres entspricht. Auf diese Weise werden nur diejenigen Schülerinnen und Schüler gefiltert, bei denen abweichend von defizitären Noten im ersten Halbjahreszeugnis zu mahnende Fächer hinzugekommen sind.</p><p>Die gefilterte Schülermenge sehen Sie im Schülercontainer. Sie können nun die Einträge bei den Schülern kontrollieren und in der Reportverwaltung den <strong>Serienbrief Mahnung gefährdete Versetzung @Erzieher.rtm ausdrucken.</strong> Hinweise zur Funktionsweise des Serienbriefs finden Sie weiter unten.</p><h3 id="schuler-filtern-um-mahnlisten-zu-drucken" tabindex="-1">Schüler filtern, um Mahnlisten zu drucken <a class="header-anchor" href="#schuler-filtern-um-mahnlisten-zu-drucken" aria-label="Permalink to &quot;Schüler filtern, um Mahnlisten zu drucken&quot;">​</a></h3><p>Sie können die zu filternde Schülergruppe einschränken, indem Sie die Schaltfläche <strong>Nur Mahnungen berücksichtigen, bei denen das Mahndatum noch nicht gesetzt ist</strong> aktivieren. Es wird nicht empfohlen, dieses Häkchen zu setzen, da es die ordnungsgemäße Funktion der Serienbriefe und Mahnreports unterwandert.</p><p>Wenn Sie die Schaltfläche <strong>Schüler filtern, um Mahnlisten zu drucken</strong> aktivieren und dann den Filter auslösen, so werden sowohl im ersten als auch im zweiten Halbjahr alle Schülerinnen und Schüler gefiltert, bei denen ein gemahntes Fach gefunden wird. Hierbei wird auch nicht unterschieden, ob ein Mahndatum hinterlegt wurde, oder nicht.</p><p>Prüfen Sie die gefilterten Personen links im Schülercontainer. Für eine Kontrollliste verwenden Sie im Basisreportordner <strong>Reports Allgemein</strong> eine dieser Vorlagen:</p><ul><li><code>Schülerliste - Klasse Gemahnte Schüler.rtm</code> für Stufen- und Schulleitung.</li><li><code>Klassenliste - Gemahnte Schüler @KL.rtm</code> für die Klassenleitung.</li></ul><p>Beide Listen zeigen die gemahnten Fächer mit Mahndatum. Dazu gehören sowohl Minderleistungen aus dem ersten Halbjahr als auch neu gemahnte Fächer.</p><h3 id="mahndatum-hinterlegen" tabindex="-1">Mahndatum hinterlegen <a class="header-anchor" href="#mahndatum-hinterlegen" aria-label="Permalink to &quot;Mahndatum hinterlegen&quot;">​</a></h3><p><img src="'+u+'" alt="Ändern oder entfernen Sie ein gesetztes Mahndatum." loading="lazy"></p><p><em>Ändern oder entfernen Sie ein gesetztes Mahndatum.</em></p><p>Aktivieren Sie <strong>Aktuelles Datum umgehend als Mahndatum setzen, sofern noch nicht vorhanden</strong>, wenn Sie beim Filtern zugleich das Datum ergänzen möchten. Der Prozess setzt es bei allen gemahnten Fächern der gefilterten Personen, denen noch ein Mahndatum fehlt. Für den anschließenden Mahnbriefdruck wird diese Einstellung empfohlen.</p><p>Ein Mahnbrief kann auch ohne Mahndatum ausgegeben werden. Das Datum dient der Information und wird im zweiten Halbjahr vom Gruppenprozess für die Filterung ausgewertet.</p><p>Die Mahnhäkchen werden in <em>Schüler ➜ Akt. Halbjahr</em> ➜ <strong>Leistungsdaten</strong> mit zwei Farben hinterlegt:</p><ul><li>Bei <em>roten</em> Mahnhäkchen wurde noch kein <strong>Mahndatum</strong> hinterlegt.</li><li>Bei <em>grünen</em> Mahnhäkchen existiert bereits ein Mahndatum.</li></ul><p>Das Mahndatum hat informativen Charakter und wird vom Gruppenprozess für die Filterung ausgewertet. Sie können für jedes Mahnhäkchen das Mahndatum über das Kontextmenü (rechte Maustaste) setzen, korrigieren oder löschen.</p>',34),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),s("Tipp")]),e("p",null,"Sie können das Mahndatum auch später setzen, wenn der Ausdruck der Mahnschreiben abgeschlossen ist. Sie können z.B. im Mahnbrief ein zukünftiges Datum angeben, um die Briefe etwas später zu verschicken. Hier bietet es sich dann an, erst zum Versanddatum das Mahndatum zu setzen.")],-1),r('<h2 id="serienbrief-mahnung-gefahrdete-versetzung" tabindex="-1">Serienbrief Mahnung gefährdete Versetzung <a class="header-anchor" href="#serienbrief-mahnung-gefahrdete-versetzung" aria-label="Permalink to &quot;Serienbrief Mahnung gefährdete Versetzung&quot;">​</a></h2><h3 id="der-report" tabindex="-1">Der Report <a class="header-anchor" href="#der-report" aria-label="Permalink to &quot;Der Report&quot;">​</a></h3><p>Das Mahnschreiben <em>Serienbrief Mahnung gefährdete Versetzung @Eltern.rtf</em> befindet sich in der Basis-Reportsammlung, welche bei der Installation von SchILD-NRW 3 mitgeliefert wird.</p><p>Eine eventuell aktualisierte Version können Sie auf der <a href="https://github.com/SVWS-NRW/Schild-NRW-3-Reports/releases" target="_blank" rel="noreferrer">Release-Seite für Schulverwaltungssoftware in GitHub</a> herunterladen.</p><p>Der Report kann an Grundschulen, weiterführenden Schulen und Berufskollegs genutzt werden.</p><h3 id="vorgaben-schulgesetz-und-ausbildungs-und-prufungsordnung" tabindex="-1">Vorgaben Schulgesetz und Ausbildungs- und Prüfungsordnung <a class="header-anchor" href="#vorgaben-schulgesetz-und-ausbildungs-und-prufungsordnung" aria-label="Permalink to &quot;Vorgaben Schulgesetz und Ausbildungs- und Prüfungsordnung&quot;">​</a></h3><p>Prinzipiell sind die Mahnbriefe Serienbriefe mit erweiterten Funktionen und Rückantwortabschnitt an die Erziehungsberechtigten.</p><p>Das Aussehen des Mahnschreibens wird in der APO-S I definiert. Dort findet sich auch der Hinweis, dass das Schreiben gemäß Anlage <em>&quot;zu verwenden&quot;</em> ist. Dies bedeutet, dass keine eigenen Texte zu verwenden sind und dass die Anlage nicht abgeändert werden darf. Die Mahnbriefe wurden in enger Rücksprache mit dem MSB konzipiert und können in den Jahrgangsstufen 3 bis EF verwendet werden.</p><p>Folgende Vorgaben wurden vom MSB gemacht:</p><ol><li>der Mahnbrief hat dem Muster aus der APO-SI zu entsprechen</li><li>ein dezidierter Abschluss muss bei einer Abschlussgefährdung nicht ausgesprochen werden</li><li>es unterschreibt immer die Klassenleitung</li><li>eine gesonderte Warnung auf die Note 6 gibt es nicht</li><li>es werden im 2. Halbjahr nur diejenigen Noten aufgelistet, welche abweichend vom ersten Halbjahr defizitär sind. Das Wort -auch- weist darauf hin, dass es vorab Defizite gab.</li><li>Der Mahnbrief wird nur an minderjährige Schulkinder versendet.</li></ol><h3 id="ausdruck-im-ersten-schulhalbjahr" tabindex="-1">Ausdruck im ersten Schulhalbjahr <a class="header-anchor" href="#ausdruck-im-ersten-schulhalbjahr" aria-label="Permalink to &quot;Ausdruck im ersten Schulhalbjahr&quot;">​</a></h3><p>Im ersten Schulhalbjahr werden alle gemahnten Fächer im Serienbrief aufgelistet. Anhand der Schulform, des Jahrgangs, der Prüfung auf Wiederholer und Verweildauer überprüft der Serienbrief zudem, ob ein Hinweis auf gefährdete Versetzung, gefährdeten Abschluss oder Schulformwechsel gegeben werden muss.</p><h3 id="ausdruck-im-zweiten-schulhalbjahr" tabindex="-1">Ausdruck im zweiten Schulhalbjahr <a class="header-anchor" href="#ausdruck-im-zweiten-schulhalbjahr" aria-label="Permalink to &quot;Ausdruck im zweiten Schulhalbjahr&quot;">​</a></h3><p>Im zweiten Halbjahr unterscheidet der Serienbrief anhand des Mahndatums:</p><ul><li>Stammt die Minderleistung bereits aus dem ersten Halbjahr, erscheint im Brief das Wort <strong>auch</strong>. Es weist auf die schon im Halbjahreszeugnis enthaltenen Minderleistungen hin.</li><li>Ist das Mahndatum leer oder wurde das Fach erst im zweiten Halbjahr gemahnt, wird das Fach im Brief einzeln aufgeführt.</li></ul><p>Anhand der Schulform, des Jahrgangs, der Prüfung auf Wiederholer und Verweildauer überprüft der Serienbrief zudem wiederum, ob ein Hinweis auf gefährdete Versetzung, gefährdeten Abschluss oder Schulformwechsel gegeben werden muss.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Mahnbriefe_drucken_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6299.</p>',18)])])}const z=i(d,[["render",l]]);export{f as __pageData,z as default};
